message.content:
{
  "description": "A large quadrupedal animal is shown in right-facing profile standing on a plain light background, covered in dense long shaggy brown fur that is darker on the lower legs and lighter tan on the muzzle and mid-flank, with a bear-like head, four thick sturdy legs ending in clawed paws, a very short stubby tail at the rear, a single large glossy black curved horn projecting from the forehead, and a large domed glossy dark reddish-brown to black segmented exoskeleton covering the entire dorsal surface from behind the shoulders to the rump.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with a broad blunt snout, black nose, small brown eyes, light tan fur on the muzzle and lower cheek, and dense brown fur over the crown and jowls",
      "where": "at the front of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy black horn with a smooth surface, curving up and forward from the forehead, with several sharp notches and points along its inner concave edge and a small secondary point at the base",
      "where": "arising from the midline of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in brown fur",
      "where": "on top of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs covered in long shaggy dark brown fur, muscular in appearance",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with long curved light gray claws protruding from the fur, five claws visible on each front paw",
      "where": "at the ends of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short small rounded nub covered in brown fur",
      "where": "at the extreme rear of the body on the left side"
    },
    {
      "part": "shell",
      "looks_like": "a large domed glossy carapace dark reddish-brown to black, with a smooth shield-like anterior section over the shoulders and a transversely ridged posterior section, with a small yellowish patch visible at the neck junction",
      "where": "covering the entire back from just behind the neck to above the tail base"
    },
    {
      "part": "plates",
      "looks_like": "about twelve overlapping hard transverse plates with pale sutures between them forming the posterior two-thirds of the shell, and a lower lateral row of small rectangular sub-plates each with two small oval holes",
      "where": "across the dorsal surface and along the lower edge of the shell where it meets the fur"
    },
    {
      "part": "markings",
      "looks_like": "a horizontal row of seven small oval dark-rimmed openings with light centers, resembling spiracles",
      "where": "on the furry flank just below the lower edge of the shell, running from mid-body to the hip"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
